mapper.select:
SELECT d.id, d.no, d.kind, d.doc_type, d.status, d.version, d.from_warehouse_id, fw.name AS from_warehouse_name, d.to_warehouse_id, tw.name AS to_warehouse_name, d.partner_id, p.short_name AS partner_name, d.source_no, d.doc_date, d.reason, d.create_by, d.create_time, agg.first_sku_id, agg.item_count, agg.total_qty, agg.total_amount FROM inv_doc d LEFT JOIN bas_warehouse fw ON fw.id = d.from_warehouse_id LEFT JOIN bas_warehouse tw ON tw.id = d.to_warehouse_id LEFT JOIN sup_supplier p ON p.id = d.partner_id LEFT JOIN LATERAL (SELECT (array_agg(i.material_sku_id ORDER BY i.seq, i.id))[1] AS first_sku_id, COUNT(*) AS item_count, SUM(i.qty) AS total_qty, SUM(i.amount) AS total_amount FROM inv_doc_item i WHERE i.doc_id = d.id) agg ON true WHERE d.kind = #{q.kind} AND d.create_by = #{scope.userId} AND d.doc_type = #{q.docType}
AND d.status IN #{s}
AND (d.from_warehouse_id = #{q.warehouseId} OR d.to_warehouse_id = #{q.warehouseId}) AND d.partner_id = #{q.partnerId} AND d.doc_date >= #{q.docDateFrom} AND d.doc_date <= #{q.docDateTo}
AND d.id IN #{id}
AND (d.no ILIKE '%' || #{q.keyword} || '%' OR d.source_no ILIKE '%' || #{q.keyword} || '%' OR d.supplier_delivery_no ILIKE '%' || #{q.keyword} || '%' OR d.logistics_no ILIKE '%' || #{q.keyword} || '%' OR EXISTS (SELECT 1 FROM inv_doc_item i JOIN bas_material_sku k ON k.id = i.material_sku_id JOIN bas_material m ON m.id = k.material_id WHERE i.doc_id = d.id AND (k.code ILIKE '%' || #{q.keyword} || '%' OR m.code ILIKE '%' || #{q.keyword} || '%' OR m.name ILIKE '%' || #{q.keyword} || '%' OR i.dye_lot ILIKE '%' || #{q.keyword} || '%')) OR upper(d.no) IN #{code} OR upper(d.source_no) IN #{code})
ORDER BY d.id DESC
